<?php $pageTitle='Reception Desk';require __DIR__.'/header.php';?><div class="head"><h1>Reception Desk</h1><form method="get"><input type="hidden" name="action" value="reception"><input type="date" name="date" value="<?=$date?>"><button class="btn primary">View</button></form></div><section class="card"><h2>Walk-in Appointment</h2><form method="post" action="index.php?action=walkin"><div class="grid3"><label>Email<input type="email" name="email" required></label><label>New patient name<input name="name"></label><label>New patient phone<input name="phone"></label><label>Doctor<select name="doctor_id" required><?php foreach($doctors as $d):?><option value="<?=$d['id']?>">Dr. <?=htmlspecialchars($d['name'])?></option><?php endforeach;?></select></label><label>Time<input type="time" name="appointment_time" required></label></div><button class="btn primary">Book Walk-in</button></form></section><section class="card table"><table><tr><th>Serial</th><th>Time</th><th>Patient</th><th>Doctor</th><th>Source</th><th>Status</th><th>Action</th></tr><?php foreach($appointments as $a):?><tr><td>#<?=$a['serial_no']?></td><td><?=date('g:i A',strtotime($a['appointment_time']))?></td><td><?=htmlspecialchars($a['patient_name'])?></td><td>Dr. <?=htmlspecialchars($a['doctor_name'])?></td><td><?=$a['source']?></td><td><span class="badge <?=$a['status']?>"><?=$a['status']?></span></td><td><?php if($a['status']==='pending'):?><a class="btn small" href="index.php?action=checkin&id=<?=$a['id']?>&date=<?=$date?>">Check In</a> <a class="danger" href="index.php?action=noshow&id=<?=$a['id']?>&date=<?=$date?>">No-show</a><?php endif;?></td></tr><?php endforeach;?></table></section><?php require __DIR__.'/footer.php';?>